CREATE TABLE arena_competitions (
 id TEXT PRIMARY KEY, title TEXT NOT NULL, description TEXT NOT NULL, rules TEXT NOT NULL,
 starts_at INTEGER NOT NULL, ends_at INTEGER NOT NULL CHECK(ends_at>starts_at),
 status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','registration','upcoming','active','completed')),
 independent INTEGER NOT NULL DEFAULT 1 CHECK(independent IN(0,1)), creator TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE arena_instructors(competition_id TEXT NOT NULL REFERENCES arena_competitions(id),user_id TEXT NOT NULL REFERENCES users(id),PRIMARY KEY(competition_id,user_id));
CREATE TABLE arena_teams(id TEXT PRIMARY KEY,competition_id TEXT NOT NULL REFERENCES arena_competitions(id),name TEXT NOT NULL,capacity INTEGER NOT NULL CHECK(capacity BETWEEN 1 AND 100),leader_id TEXT REFERENCES users(id),UNIQUE(competition_id,name));
CREATE TABLE arena_participants(competition_id TEXT NOT NULL REFERENCES arena_competitions(id),user_id TEXT NOT NULL REFERENCES users(id),team_id TEXT REFERENCES arena_teams(id),role TEXT CHECK(role IN('red','blue','soc','auditor')),status TEXT NOT NULL DEFAULT 'requested' CHECK(status IN('requested','assigned')),joined_at TEXT NOT NULL DEFAULT(datetime('now')),PRIMARY KEY(competition_id,user_id));
CREATE TABLE arena_challenges(id TEXT PRIMARY KEY,competition_id TEXT NOT NULL REFERENCES arena_competitions(id),title TEXT NOT NULL,description TEXT NOT NULL,instructions TEXT NOT NULL,objectives TEXT NOT NULL,category TEXT NOT NULL,difficulty TEXT NOT NULL,points INTEGER NOT NULL CHECK(points BETWEEN 1 AND 1000),role TEXT NOT NULL CHECK(role IN('red','blue','soc','auditor','all')),team_id TEXT REFERENCES arena_teams(id),format TEXT NOT NULL CHECK(format IN('choice','short','flag','report','evidence')),choices TEXT NOT NULL DEFAULT '[]',criteria TEXT NOT NULL,hints TEXT NOT NULL,starts_at INTEGER NOT NULL,ends_at INTEGER NOT NULL CHECK(ends_at>starts_at),time_limit INTEGER CHECK(time_limit IS NULL OR time_limit BETWEEN 60 AND 86400),answer_hash TEXT,answer_salt TEXT);
CREATE TABLE arena_attempts(challenge_id TEXT NOT NULL REFERENCES arena_challenges(id),user_id TEXT NOT NULL REFERENCES users(id),started_at INTEGER NOT NULL,PRIMARY KEY(challenge_id,user_id));
CREATE TABLE arena_submissions(id TEXT PRIMARY KEY,competition_id TEXT NOT NULL REFERENCES arena_competitions(id),challenge_id TEXT NOT NULL REFERENCES arena_challenges(id),user_id TEXT NOT NULL REFERENCES users(id),answer TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('pending','correct','incorrect','reviewed')),request_key TEXT NOT NULL,created_at INTEGER NOT NULL,UNIQUE(user_id,request_key));
CREATE INDEX arena_submission_comp ON arena_submissions(competition_id,created_at);
CREATE TABLE arena_awards(competition_id TEXT NOT NULL REFERENCES arena_competitions(id),challenge_id TEXT NOT NULL REFERENCES arena_challenges(id),user_id TEXT NOT NULL REFERENCES users(id),submission_id TEXT NOT NULL REFERENCES arena_submissions(id),points INTEGER NOT NULL CHECK(points>=0),actor TEXT NOT NULL REFERENCES users(id),reason TEXT NOT NULL,PRIMARY KEY(challenge_id,user_id));
CREATE TABLE arena_score_events(id INTEGER PRIMARY KEY AUTOINCREMENT,competition_id TEXT NOT NULL,challenge_id TEXT NOT NULL,user_id TEXT NOT NULL,actor TEXT NOT NULL,previous_points INTEGER NOT NULL,new_points INTEGER NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE TRIGGER arena_award_limit BEFORE INSERT ON arena_awards BEGIN SELECT CASE WHEN NEW.points>(SELECT points FROM arena_challenges WHERE id=NEW.challenge_id) THEN RAISE(ABORT,'Arena score limit') END; END;
CREATE TRIGGER arena_award_limit_update BEFORE UPDATE ON arena_awards BEGIN SELECT CASE WHEN NEW.points>(SELECT points FROM arena_challenges WHERE id=NEW.challenge_id) THEN RAISE(ABORT,'Arena score limit') END; END;
CREATE TRIGGER arena_award_created AFTER INSERT ON arena_awards BEGIN INSERT INTO arena_score_events(competition_id,challenge_id,user_id,actor,previous_points,new_points,reason) VALUES(NEW.competition_id,NEW.challenge_id,NEW.user_id,NEW.actor,0,NEW.points,NEW.reason); END;
CREATE TRIGGER arena_award_updated AFTER UPDATE ON arena_awards WHEN OLD.points!=NEW.points BEGIN INSERT INTO arena_score_events(competition_id,challenge_id,user_id,actor,previous_points,new_points,reason) VALUES(NEW.competition_id,NEW.challenge_id,NEW.user_id,NEW.actor,OLD.points,NEW.points,NEW.reason); END;
CREATE TABLE arena_achievements(competition_id TEXT NOT NULL,user_id TEXT NOT NULL REFERENCES users(id),badge TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT(datetime('now')),PRIMARY KEY(competition_id,user_id,badge));
CREATE TABLE arena_announcements(id TEXT PRIMARY KEY,competition_id TEXT NOT NULL REFERENCES arena_competitions(id),body TEXT NOT NULL,actor TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE TABLE arena_alerts(id TEXT PRIMARY KEY,competition_id TEXT NOT NULL REFERENCES arena_competitions(id),team_id TEXT REFERENCES arena_teams(id),title TEXT NOT NULL,details TEXT NOT NULL,severity TEXT NOT NULL CHECK(severity IN('low','medium','high','critical')),status TEXT NOT NULL DEFAULT 'new' CHECK(status IN('new','investigating','contained','resolved','closed')),created_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE TABLE arena_notes(id TEXT PRIMARY KEY,alert_id TEXT NOT NULL REFERENCES arena_alerts(id),actor TEXT NOT NULL REFERENCES users(id),body TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE INDEX arena_challenge_comp ON arena_challenges(competition_id);
CREATE INDEX arena_alert_comp ON arena_alerts(competition_id);
CREATE INDEX arena_award_comp ON arena_awards(competition_id,user_id);
CREATE TRIGGER arena_submission_guard BEFORE INSERT ON arena_submissions BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM arena_competitions c JOIN arena_challenges ch ON ch.competition_id=c.id JOIN arena_participants p ON p.competition_id=c.id AND p.user_id=NEW.user_id JOIN users u ON u.id=p.user_id JOIN arena_attempts a ON a.challenge_id=ch.id AND a.user_id=p.user_id WHERE c.id=NEW.competition_id AND ch.id=NEW.challenge_id AND c.status='active' AND u.status='active' AND p.status='assigned' AND (ch.role='all' OR ch.role=p.role) AND (ch.team_id IS NULL OR ch.team_id=p.team_id) AND NEW.created_at>=c.starts_at AND NEW.created_at<c.ends_at AND NEW.created_at>=ch.starts_at AND NEW.created_at<ch.ends_at AND (ch.time_limit IS NULL OR NEW.created_at<a.started_at+ch.time_limit*1000)) THEN RAISE(ABORT,'Arena submission is not eligible') END;
END;
CREATE TRIGGER arena_membership_lock BEFORE UPDATE ON arena_participants WHEN (OLD.team_id IS NOT NEW.team_id OR OLD.role IS NOT NEW.role) AND EXISTS(SELECT 1 FROM arena_submissions s WHERE s.competition_id=OLD.competition_id AND s.user_id=OLD.user_id) BEGIN SELECT RAISE(ABORT,'Arena membership is locked'); END;
CREATE TRIGGER arena_leader_move AFTER UPDATE ON arena_participants WHEN OLD.team_id IS NOT NEW.team_id BEGIN UPDATE arena_teams SET leader_id=NULL WHERE id=OLD.team_id AND leader_id=OLD.user_id; END;
